// Legacy wire shape: the tags are the contract, not the field names
type legacyQuote struct {
    SKU      string `json:"SKU"`
    Price    string `json:"unit_price"` // the old system sends decimals as text
    Currency string `json:"ccy,omitempty"`
}
func (w *Window) Quote(ctx context.Context, raw []byte) ([]byte, error) {
    var in legacyQuote
    if err := json.Unmarshal(raw, &in); err != nil { return nil, legacyErr(err) }
    q, err := w.core.Quote(ctx, in.SKU)          // canonical result
    if err != nil { return nil, legacyErr(err) } // error codes are shape too
    return json.Marshal(toLegacy(q))
}
